import sys

Mod = 998244353
MAX = 500

# Precompute factorials, inverse factorials, and modular inverses
fac = [1] * (MAX + 1)
inv = [1] * (MAX + 1)
finv = [1] * (MAX + 1)
for i in range(2, MAX + 1):
    fac[i] = fac[i - 1] * i % Mod
    inv[i] = Mod - inv[Mod % i] * (Mod // i) % Mod
    finv[i] = finv[i - 1] * inv[i] % Mod

# Precompute powers: pow_table[i][j] = i^j mod Mod
pow_table = [[0] * 501 for _ in range(501)]
for i in range(501):
    pow_table[i][0] = 1
    for j in range(500):
        pow_table[i][j + 1] = pow_table[i][j] * i % Mod

def ModCombination(n, k):
    if n < k:
        return 0
    ret = 1
    while n > 0 or k > 0:
        ni = n % Mod
        ki = k % Mod
        if ni < ki:
            return 0
        ret = ret * fac[ni] % Mod * finv[ki] % Mod * finv[ni - ki] % Mod
        n //= Mod
        k //= Mod
    return ret

def solve():
    data = sys.stdin.read().split()
    if not data:
        return
    n = int(data[0])
    x = int(data[1])

    dp = [[0] * 501 for _ in range(501)]

    for i in range(2, n + 1):
        jj = min(x, i - 1)
        for j in range(1, jj + 1):
            dp[i][j] = (pow_table[j][i] - pow_table[j - 1][i]) % Mod

    for i in range(2, n + 1):
        for j in range(1, x + 1):
            if dp[i][j] == 0:
                continue
            for k in range(0, n - i + 1):
                nj = j + i + k - 1
                if nj > x:
                    break
                comb = ModCombination(i + k, k)
                val = dp[i][j] * pow_table[i + k - 1][k] % Mod * comb % Mod
                dp[i + k][nj] = (dp[i + k][nj] + val) % Mod

    ans = sum(dp[n][j] for j in range(1, x + 1)) % Mod
    print((ans % Mod + Mod) % Mod)

if __name__ == "__main__":
    solve()

